challenge.starter:
#include <stdio.h>

int main(void) {
    // TODO: 输入正整数 limit（1～100），使用 while(1) 和 break，输出最小的满足 2*k >= limit 的非负整数 k

    return 0;
}

challenge.solution:
#include <stdio.h>

int main(void) {
    int limit, k = 0;
    if (scanf("%d", &limit) != 1) { return 1; }
    while (1) {
        if (2 * k >= limit) { break; }
        k++;
    }
    printf("%d\n", k);
    return 0;
}

lessons.syntax:
for (int i = 0; i < n; i++) {
    if (x > 0) { sum += x; }
}

lessons.example:
#include <stdio.h>

int main(void) {
    int n, x, count = 0;
    if (scanf("%d", &n) != 1) { return 1; }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &x) != 1) { return 1; }
        if (x > 0) { count++; }
    }
    printf("%d\n", count);
    return 0;
}

challenge.starter:
#include <stdio.h>

int main(void) {
    // TODO: 先输入 n（1～20），再输入 n 个整数（-100～100）

    return 0;
}

challenge.solution:
#include <stdio.h>

int main(void) {
    int n, x, sum = 0, count = 0;
    if (scanf("%d", &n) != 1) { return 1; }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &x) != 1) { return 1; }
        if (x > 0) { sum += x; count++; }
    }
    printf("%d %d\n", sum, count);
    return 0;
}
